### Multi-User Conflict-Free Undo/Redo & Spatial Bounding Box Invalidation

#### 1. Architecture & Codebase Inspection Summary
- **`CanvasStateManager`** (`state-crdt.ts`): Stores whiteboard elements in a map keyed by element ID and handles remote patch application based on monotonic CRDT versioning (`incoming.version > current.version`).
- **`CanvasRenderer`** (`canvas-engine.ts`): Offscreen canvas rendering engine that iterates through active elements and renders shapes (`rect`, etc.) onto the canvas 2D context.
- **`SyncSocketClient`** (`ws-client.ts`): Dispatches websocket frames (`ELEMENT_SYNC`) to broadcast local state mutations to connected peers.

#### 2. Multi-User Selective Undo/Redo Strategy
To achieve conflict-free undo/redo across multiple concurrent peers:
1. **Per-Peer History Stacks**: Undo and redo stacks are isolated per `peerId`, ensuring that peer A undoing an operation does not disrupt peer B's independent concurrent edits.
2. **CRDT Monotonicity**: When an element state is reverted during undo or re-applied during redo, its `version` is incremented beyond the current version:
   $$\text{newVersion} = \max(\text{currentVersion}, \text{targetVersion}) + 1$$
   This ensures that remote peers receive and accept the reverted state via `applyRemotePatch`.
3. **Tombstone / Deletion Handling**: When an undo reverts an element creation, the element is soft-deleted or removed from the active map, and an update is propagated.

---

### Completed TypeScript Implementation

```typescript
import { WhiteboardElement } from "./state-crdt";

export interface BoundingBox {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
}

export interface PeerAction {
  elementId: string;
  before: WhiteboardElement | null;
  after: WhiteboardElement | null;
}

export class CollaborativeCanvasStateManager {
  private elements: Map<string, WhiteboardElement> = new Map();
  private peerUndoStacks: Map<string, PeerAction[]> = new Map();
  private peerRedoStacks: Map<string, PeerAction[]> = new Map();

  /**
   * Applies an incoming patch from CRDT / WebSocket.
   */
  public applyRemotePatch(incoming: WhiteboardElement): boolean {
    const current = this.elements.get(incoming.id);
    if (!current || incoming.version > current.version) {
      if ((incoming as any).isDeleted) {
        this.elements.delete(incoming.id);
      } else {
        this.elements.set(incoming.id, incoming);
      }
      return true;
    }
    return false;
  }

  /**
   * Records a local mutation performed by peerId.
   */
  public recordMutation(peerId: string, before: WhiteboardElement | null, after: WhiteboardElement | null): void {
    if (!this.peerUndoStacks.has(peerId)) {
      this.peerUndoStacks.set(peerId, []);
    }
    if (!this.peerRedoStacks.has(peerId)) {
      this.peerRedoStacks.set(peerId, []);
    }

    const elementId = (after || before)!.id;
    this.peerUndoStacks.get(peerId)!.push({ elementId, before, after });
    // Clear redo stack on new operation
    this.peerRedoStacks.get(peerId)!.length = 0;

    if (after) {
      this.elements.set(elementId, after);
    } else {
      this.elements.delete(elementId);
    }
  }

  /**
   * Selective undo for a specific peerId.
   * Returns the updated element array after the undo operation.
   */
  public undo(peerId: string): WhiteboardElement[] {
    const undoStack = this.peerUndoStacks.get(peerId);
    if (!undoStack || undoStack.length === 0) {
      return this.getAllElements();
    }

    const action = undoStack.pop()!;
    if (!this.peerRedoStacks.has(peerId)) {
      this.peerRedoStacks.set(peerId, []);
    }
    this.peerRedoStacks.get(peerId)!.push(action);

    const current = this.elements.get(action.elementId);
    const currentVer = current ? current.version : 0;

    if (action.before === null) {
      // Element was created in this action -> undo means deleting it
      this.elements.delete(action.elementId);
    } else {
      // Revert to before state, incrementing version to guarantee CRDT ordering
      const reverted: WhiteboardElement = {
        ...action.before,
        version: Math.max(currentVer, action.before.version) + 1,
        authorId: peerId
      };
      this.elements.set(action.elementId, reverted);
    }

    return this.getAllElements();
  }

  /**
   * Selective redo for a specific peerId.
   * Returns the updated element array after the redo operation.
   */
  public redo(peerId: string): WhiteboardElement[] {
    const redoStack = this.peerRedoStacks.get(peerId);
    if (!redoStack || redoStack.length === 0) {
      return this.getAllElements();
    }

    const action = redoStack.pop()!;
    this.peerUndoStacks.get(peerId)!.push(action);

    const current = this.elements.get(action.elementId);
    const currentVer = current ? current.version : 0;

    if (action.after === null) {
      // Re-delete
      this.elements.delete(action.elementId);
    } else {
      // Re-apply after state with monotonically advanced version
      const reApplied: WhiteboardElement = {
        ...action.after,
        version: Math.max(currentVer, action.after.version) + 1,
        authorId: peerId
      };
      this.elements.set(action.elementId, reApplied);
    }

    return this.getAllElements();
  }

  public getAllElements(): WhiteboardElement[] {
    return Array.from(this.elements.values());
  }
}

/**
 * Computes the minimal axis-aligned bounding box covering all regions
 * dirtied by additions, modifications, or deletions between two state snapshots.
 */
export function computeDirtyBounds(
  before: WhiteboardElement[],
  after: WhiteboardElement[]
): BoundingBox {
  const beforeMap = new Map<string, WhiteboardElement>(before.map(el => [el.id, el]));
  const afterMap = new Map<string, WhiteboardElement>(after.map(el => [el.id, el]));

  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  let hasDirty = false;

  const includeBounds = (el: WhiteboardElement) => {
    hasDirty = true;
    minX = Math.min(minX, el.x);
    minY = Math.min(minY, el.y);
    maxX = Math.max(maxX, el.x + el.width);
    maxY = Math.max(maxY, el.y + el.height);
  };

  // 1. Check all elements in 'before' for deletions or mutations
  for (const [id, b] of beforeMap.entries()) {
    const a = afterMap.get(id);
    if (!a) {
      // Deleted: dirty before region
      includeBounds(b);
    } else if (
      b.x !== a.x ||
      b.y !== a.y ||
      b.width !== a.width ||
      b.height !== a.height ||
      b.stroke !== a.stroke ||
      b.type !== a.type ||
      b.version !== a.version
    ) {
      // Modified: both previous and new bounding boxes must be redrawn
      includeBounds(b);
      includeBounds(a);
    }
  }

  // 2. Check all elements in 'after' for newly created elements
  for (const [id, a] of afterMap.entries()) {
    if (!beforeMap.has(id)) {
      // Created: dirty after region
      includeBounds(a);
    }
  }

  if (!hasDirty) {
    return { minX: 0, minY: 0, maxX: 0, maxY: 0 };
  }

  return { minX, minY, maxX, maxY };
}
```

---

### Invalidation & Offscreen Render Loop Integration
When an `undo` or `redo` is triggered:
```typescript
const beforeElements = stateManager.getAllElements();
const afterElements = stateManager.undo(localPeerId);
const dirtyRect = computeDirtyBounds(beforeElements, afterElements);

// Clip canvas context to dirty bounds to skip repainting unchanged canvas areas
if (dirtyRect.maxX > dirtyRect.minX && dirtyRect.maxY > dirtyRect.minY) {
  renderer.renderDirtyRegion(dirtyRect);
}
```
